"use client";

export { AomiPrivyProvider, type AomiPrivyProviderProps } from "./privy";
export { PrivyDelegationProvider } from "./privy-delegation";
export {
  usePrivyDelegation,
  type PrivyDelegationContextValue,
} from "./privy-delegation-context";
export { privyPlugin, registerAomiPrivyWalletProvider } from "./privy-plugin";
export { privyAuth, type PrivyAuthOptions } from "./widget-auth";

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { Chain, Hex } from "viem";
import type { WalletEip712Payload } from "@aomi-labs/react";
import { toViemSignTypedDataArgs } from "@aomi-labs/react";
import { AomiWalletKitComposer } from "../../composer/AomiWalletKitComposer";
import type { AuthRuntime, ExecutionRuntime } from "../../composer/types";
import { useResolvedAccountRuntime } from "../../account/use-resolved-account-runtime";
import { buildEvmExecutionRuntime } from "../../execution/execution-runtime";
import { useAomiWalletNetworkPreferences } from "../../network-preferences";
import { useEvmWalletRuntime } from "../../runtime/evm/wallet-runtime";
import {
  useMergedSvmWallet,
  useSafeSvmWallet,
  useSvmWalletRuntime,
  type SafeSvmWalletState,
} from "../../runtime/svm/wallet-runtime";
import { REGISTRY_STORAGE_KEY } from "../../registry/types";
import type { AomiAccount, AomiAccountCredential } from "../../types";
import type { AccountConfig, ExecutionConfig } from "../../config/types";
import {
  inferPrivyAuthMethod,
  inferPrivyPrimaryLabel,
  pickPrivyEmbeddedEvmWallet,
  pickPrivyEmbeddedEvmUserWallet,
  privyLoginMethodsToOptions,
  useSafePrivy,
  useSafeSmartWallets,
  useSafeSvmWallets,
  useSafeWallets,
} from "./privy-auth";
import type { PrivyClientConfig } from "@privy-io/react-auth";
import { buildPrivySvmWalletState } from "./privy-svm";
import { sendPrivySmartWalletTransaction } from "./privy-execution";
import { useEmbeddedSessionSource } from "../sources/embedded-session-source";

export type AomiPrivyPluginProviderProps = {
  children: ReactNode;
  supportedChains: readonly Chain[];
  loginMethods?: PrivyClientConfig["loginMethods"];
  execution?: ExecutionConfig;
  account?: AccountConfig;
  preferDirectSend?: boolean;
  externalSvmWallet?: SafeSvmWalletState;
};

export function AomiPrivyPluginProvider({
  children,
  supportedChains,
  loginMethods,
  execution,
  account,
  preferDirectSend = true,
  externalSvmWallet,
}: AomiPrivyPluginProviderProps) {
  const privy = useSafePrivy();
  const { client: smartWalletClient, getClientForChain } =
    useSafeSmartWallets();
  const { wallets: solanaWallets } = useSafeSvmWallets();
  const { wallets: connectedWallets } = useSafeWallets();
  const contextSvmWallet = useSafeSvmWallet();
  const [activeSolanaAddress, setActiveSolanaAddress] = useState<
    string | undefined
  >();
  const {
    selectedEvmChainId,
    selectedSolanaNetwork,
    setSelectedEvmChainId,
    setSelectedSolanaNetworkId,
    supportedSolanaNetworks,
  } = useAomiWalletNetworkPreferences();
  const evmRuntime = useEvmWalletRuntime({
    configuredChains: supportedChains,
    selectedEvmChainId,
    setSelectedEvmChainId,
    storageKey: REGISTRY_STORAGE_KEY,
    providerHooks: { providerLogout: privy.logout },
  });
  const startPrivyAuthFlow = useCallback(
    (reason: string) => {
      evmRuntime.registryStore.dispatch({
        type: "provider/auth-flow-started",
        reason,
        now: Date.now(),
      });
    },
    [evmRuntime.registryStore],
  );
  const smartAddress = smartWalletClient?.account?.address as Hex | undefined;
  // Embedded EVM EOA from Privy's connected-wallet snapshot or user record.
  // Surfaced as a synthetic EVM connection so it appears in "Connected now"
  // with write capability, mirroring the Para session source. Falls back to
  // the smart wallet address when one is active so account-abstracted
  // execution stays the primary surface when present.
  const embeddedEvmWallet = pickPrivyEmbeddedEvmWallet(connectedWallets);
  const embeddedEvmUserWallet = pickPrivyEmbeddedEvmUserWallet(privy.user);
  const embeddedEvmAddress = (embeddedEvmWallet?.address ??
    embeddedEvmUserWallet?.address) as Hex | undefined;
  // Backend-owned AA treats Privy's embedded EOA as the owner and provisions
  // its executor server-side. Never replace the owner identity with Privy's
  // client-managed smart account when both are present.
  const sessionEvmAddress = embeddedEvmAddress ?? smartAddress ?? null;
  const sessionReady =
    privy.authenticated &&
    Boolean(embeddedEvmWallet || embeddedEvmUserWallet || smartAddress);
  const activeSolanaWallet =
    solanaWallets.find((wallet) => wallet.address === activeSolanaAddress) ??
    solanaWallets[0];
  const privySvmWallet = useMemo(
    () =>
      buildPrivySvmWalletState({
        wallet: activeSolanaWallet,
        wallets: solanaWallets,
        setActiveAddress: setActiveSolanaAddress,
      }),
    [activeSolanaWallet, solanaWallets],
  );
  const svmWallet = useMergedSvmWallet(
    externalSvmWallet ?? contextSvmWallet,
    privySvmWallet,
  );

  useEffect(() => {
    if (
      activeSolanaAddress &&
      solanaWallets.some((wallet) => wallet.address === activeSolanaAddress)
    ) {
      return;
    }
    setActiveSolanaAddress(solanaWallets[0]?.address);
  }, [activeSolanaAddress, solanaWallets]);

  useEmbeddedSessionSource(evmRuntime.registryStore, {
    up: sessionReady,
    providerId: "privy",
    uid: "privy-smart-session",
    stableId: "privy",
    walletName: "Privy Smart Wallet",
    embeddedEvmAddress: sessionEvmAddress,
    chainId: selectedEvmChainId,
  });

  const authMethod = inferPrivyAuthMethod(privy.user);
  const primaryLabel = inferPrivyPrimaryLabel(privy.user);
  const authRuntime = useMemo<AuthRuntime>(
    () => ({
      provider: "privy",
      sessionProvider: "privy",
      embeddedProvider: "privy",
      providerLabel: "Privy",
      status: !privy.ready
        ? "booting"
        : privy.authenticated
          ? "authenticated"
          : "unauthenticated",
      subject: privy.user?.id,
      primaryLabel,
      authMethod,
      authValue: primaryLabel,
      methods: privyLoginMethodsToOptions(loginMethods),
      canOpenModal: Boolean(privy.login),
      startFlow: startPrivyAuthFlow,
      login: async (reason = "provider-auth-modal") => {
        evmRuntime.registryStore.dispatch({
          type: "user/provider-reconnect-requested",
          now: Date.now(),
        });
        startPrivyAuthFlow(reason);
        await privy.login();
      },
      logout: privy.logout,
      getCredential:
        (privy.getIdentityToken ?? privy.getAccessToken)
          ? async (): Promise<AomiAccountCredential | null> => {
              const identityToken = (await privy.getIdentityToken?.())?.trim();
              if (identityToken) {
                return {
                  provider: "privy",
                  tokenKind: "identity_token",
                  providerToken: identityToken,
                };
              }
              const accessToken = (await privy.getAccessToken?.())?.trim();
              return accessToken
                ? {
                    provider: "privy",
                    tokenKind: "access_token",
                    providerToken: accessToken,
                  }
                : null;
            }
          : undefined,
    }),
    [
      authMethod,
      loginMethods,
      primaryLabel,
      privy.authenticated,
      privy.getAccessToken,
      privy.getIdentityToken,
      privy.login,
      privy.logout,
      privy.ready,
      privy.user?.id,
      evmRuntime.registryStore,
      startPrivyAuthFlow,
    ],
  );

  const transformPrivyAccounts = useCallback(
    (accounts: AomiAccount[]) =>
      accounts.map((account) => {
        if (
          !privy.authenticated ||
          account.provider !== "privy" ||
          (account.walletKind !== "embedded" &&
            account.walletKind !== "smart_account")
        ) {
          return account;
        }
        return {
          ...account,
          linkedVia: account.linkedVia ?? "privy",
          actions: [{ kind: "signout" as const, label: "Sign out" }],
        };
      }),
    [privy.authenticated],
  );

  const svmRuntime = useSvmWalletRuntime({
    preferDirectSend,
    registryStore: evmRuntime.registryStore,
    selectedNetwork: selectedSolanaNetwork,
    supportedNetworks: supportedSolanaNetworks,
    setSelectedNetworkId: setSelectedSolanaNetworkId,
    wallet: svmWallet,
  });
  const executionRuntime = useMemo<ExecutionRuntime>(
    () => ({
      evm: buildEvmExecutionRuntime(evmRuntime, {
        signMessage:
          embeddedEvmWallet && embeddedEvmAddress
            ? async (payload: WalletEip712Payload) => {
                const owner = payload.signer ?? embeddedEvmAddress;
                if (owner.toLowerCase() !== embeddedEvmAddress.toLowerCase()) {
                  throw new Error(
                    "The active Privy EOA is not the requested signer",
                  );
                }
                if (!payload.non_typed_data) {
                  throw new Error("Missing non_typed_data payload");
                }
                const provider = await embeddedEvmWallet.getEthereumProvider();
                const signature = await provider.request({
                  method: "personal_sign",
                  params: [payload.non_typed_data, owner],
                });
                if (typeof signature !== "string") {
                  throw new Error("Privy returned an invalid signature");
                }
                return { signature };
              }
            : undefined,
        sendTransaction:
          execution?.aa === "off"
            ? undefined
            : smartWalletClient
              ? async (payload) =>
                  sendPrivySmartWalletTransaction({
                    payload,
                    smartWalletClient,
                    getClientForChain,
                    wagmiChainId: evmRuntime.activeEvmConnection?.chainId,
                    smartAddress,
                  })
              : undefined,
        signTypedData:
          embeddedEvmWallet && embeddedEvmAddress
            ? async (payload: WalletEip712Payload) => {
                const owner = payload.signer ?? embeddedEvmAddress;
                if (owner.toLowerCase() !== embeddedEvmAddress.toLowerCase()) {
                  throw new Error(
                    "The active Privy EOA is not the requested signer",
                  );
                }
                const args = toViemSignTypedDataArgs(payload);
                if (!args) throw new Error("Missing typed_data payload");
                const provider = await embeddedEvmWallet.getEthereumProvider();
                const signature = await provider.request({
                  method: "eth_signTypedData_v4",
                  params: [owner, JSON.stringify(args)],
                });
                if (typeof signature !== "string") {
                  throw new Error("Privy returned an invalid signature");
                }
                return { signature };
              }
            : smartWalletClient
              ? async (payload: WalletEip712Payload) => {
                  const args = toViemSignTypedDataArgs(payload);
                  if (!args) throw new Error("Missing typed_data payload");
                  const signature = await smartWalletClient.signTypedData(
                    args as never,
                  );
                  return { signature };
                }
              : undefined,
      }),
    }),
    [
      embeddedEvmAddress,
      embeddedEvmWallet,
      evmRuntime,
      execution,
      getClientForChain,
      smartAddress,
      smartWalletClient,
    ],
  );
  const accountRuntime = useResolvedAccountRuntime({
    account,
    auth: authRuntime,
    evm: evmRuntime,
    svm: svmRuntime,
  });

  return (
    <AomiWalletKitComposer
      auth={authRuntime}
      account={accountRuntime}
      evm={evmRuntime}
      svm={svmRuntime}
      execution={executionRuntime}
      transformAccounts={transformPrivyAccounts}
      supportedChains={supportedChains}
    >
      {children}
    </AomiWalletKitComposer>
  );
}

"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  PrivyProvider as PrivyAuthProvider,
  type PrivyClientConfig,
} from "@privy-io/react-auth";
import { SmartWalletsProvider } from "@privy-io/react-auth/smart-wallets";
import { WagmiProvider } from "@privy-io/wagmi";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import type { Chain } from "viem";
import {
  arbitrum,
  base,
  linea,
  lineaSepolia,
  mainnet,
  optimism,
  polygon,
  sepolia,
} from "wagmi/chains";
import { ExtUserProvider } from "@aomi-labs/react";
import { arcTestnet, megaeth, robinhood } from "@aomi-labs/client";
import { createAomiEvmConfig } from "../../catalog/evm-connector-catalog";
import {
  AomiWalletNetworkPreferencesProvider,
  useAomiWalletNetworkPreferences,
} from "../../network-preferences";
import { normalizeSvmNetworkOptions } from "../../catalog/svm-networks";
import type { SvmCluster, SvmNetworkOption } from "../../types";
import { safeEnv } from "../../env";
import type { EvmWalletsConfig, ExecutionConfig } from "../../config/types";
import { AomiPrivyPluginProvider } from "./PrivyPluginProvider";
import { buildPrivyClientConfig } from "./privy-auth";

const defaultNetworks = [
  mainnet,
  arbitrum,
  optimism,
  base,
  polygon,
  sepolia,
  linea,
  lineaSepolia,
  robinhood,
  megaeth,
  arcTestnet,
] as const;

export type AomiPrivyProviderProps = {
  children: ReactNode;
  appId?: string;
  appName?: string;
  appLogoUrl?: string;
  networks?: readonly [Chain, ...Chain[]];
  wallets?: EvmWalletsConfig;
  loginMethods?: PrivyClientConfig["loginMethods"];
  walletConnectProjectId?: string;
  execution?: ExecutionConfig;
  solana?: {
    networks?: readonly SvmNetworkOption[];
    cluster?: SvmCluster;
    rpcHttpUrl?: string;
    rpcWsUrl?: string;
    preferDirectSend?: boolean;
  };
};

function AomiPrivyProviderInner({
  children,
  appId = safeEnv(() => process.env.NEXT_PUBLIC_PRIVY_APP_ID),
  appName = "Aomi",
  appLogoUrl,
  networks = defaultNetworks,
  wallets,
  loginMethods,
  execution,
  solana,
  walletConnectProjectId = safeEnv(
    () => process.env.NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID,
  ),
}: AomiPrivyProviderProps) {
  const [queryClient] = useState(() => new QueryClient());
  const { selectedEvmChainId } = useAomiWalletNetworkPreferences();
  const defaultEvmChain =
    networks.find((chain) => chain.id === selectedEvmChainId) ?? networks[0];
  const wagmiConfig = useMemo(
    () =>
      createAomiEvmConfig({
        chains: networks,
        preset: wallets?.preset,
        wallets: wallets?.wallets,
        connectors: wallets?.connectors,
        walletConnectProjectId,
        coinbase: wallets?.coinbase,
        appName,
        appLogoUrl,
        transports: wallets?.transports,
      }),
    [appLogoUrl, appName, networks, walletConnectProjectId, wallets],
  );

  const adapter = (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <SmartWalletsProvider>
          <AomiPrivyPluginProvider
            supportedChains={networks}
            loginMethods={loginMethods}
            execution={execution}
            preferDirectSend={solana?.preferDirectSend}
          >
            {children}
          </AomiPrivyPluginProvider>
        </SmartWalletsProvider>
      </WagmiProvider>
    </QueryClientProvider>
  );

  if (!appId) return adapter;

  return (
    <PrivyAuthProvider
      appId={appId}
      config={buildPrivyClientConfig({
        appLogoUrl,
        appName,
        loginMethods,
        defaultChain: defaultEvmChain,
        supportedChains: networks,
        walletConnectProjectId,
      })}
    >
      {adapter}
    </PrivyAuthProvider>
  );
}

export function AomiPrivyProvider({
  networks = defaultNetworks,
  wallets,
  solana,
  ...rest
}: AomiPrivyProviderProps) {
  const supportedSolanaNetworks = useMemo(
    () => normalizeSvmNetworkOptions(solana),
    [solana],
  );

  return (
    <AomiWalletNetworkPreferencesProvider
      evmChains={networks}
      solanaNetworks={supportedSolanaNetworks}
      storageKey="privy"
    >
      <ExtUserProvider>
        <AomiPrivyProviderInner
          {...rest}
          networks={networks}
          solana={solana}
          wallets={wallets}
        />
      </ExtUserProvider>
    </AomiWalletNetworkPreferencesProvider>
  );
}

"use client";

import {
  usePrivy,
  useWallets,
  type ConnectedWallet,
  type PrivyClientConfig,
} from "@privy-io/react-auth";
import { useSolanaWallets } from "@privy-io/react-auth/solana";
import { useSmartWallets } from "@privy-io/react-auth/smart-wallets";
import type { Chain } from "viem";
import type { AomiLoginMethod, AomiWalletOption } from "../../types";
import type { AuthMethodId } from "../../config/types";

export type PrivyHook = ReturnType<typeof usePrivy>;
export type PrivyAccessTokenHook = PrivyHook & {
  getAccessToken?: () => Promise<string | null>;
  getIdentityToken?: () => Promise<string | null>;
};
export type SmartWalletsHook = ReturnType<typeof useSmartWallets>;
export type SolanaWalletsHook = ReturnType<typeof useSolanaWallets>;
export type WalletsHook = ReturnType<typeof useWallets>;
export type PrivyUser = PrivyHook["user"];
export type PrivySolanaWallet = SolanaWalletsHook["wallets"][number];
export type PrivyConnectedWallet = ConnectedWallet;
export type PrivyEmbeddedEvmUserWallet = {
  id?: string | null;
  address: string;
  chainType?: string;
  walletClientType?: string;
  connectorType?: string;
  imported?: boolean;
};

const DISCONNECTED_PRIVY: PrivyAccessTokenHook = {
  ready: false,
  authenticated: false,
  user: null,
  login: async () => undefined,
  logout: async () => undefined,
  getAccessToken: async () => null,
  getIdentityToken: async () => null,
} as unknown as PrivyAccessTokenHook;

const DISCONNECTED_SMART_WALLETS: SmartWalletsHook = {
  client: undefined,
  getClientForChain: async () => undefined,
} as unknown as SmartWalletsHook;

const DISCONNECTED_SOLANA_WALLETS: SolanaWalletsHook = {
  wallets: [],
  ready: false,
} as unknown as SolanaWalletsHook;

const DISCONNECTED_WALLETS: WalletsHook = {
  wallets: [],
  ready: false,
} as unknown as WalletsHook;

const AOMI_LOGIN_METHODS = new Set<AomiLoginMethod>([
  "google",
  "apple",
  "facebook",
  "x",
  "discord",
  "github",
  "farcaster",
  "telegram",
  "email",
  "phone",
  "wagmi",
  "passkey",
  "wallet",
]);

export function useSafePrivy(): PrivyAccessTokenHook {
  try {
    return usePrivy() as PrivyAccessTokenHook;
  } catch {
    return DISCONNECTED_PRIVY;
  }
}

export function useSafeSmartWallets(): SmartWalletsHook {
  try {
    return useSmartWallets();
  } catch {
    return DISCONNECTED_SMART_WALLETS;
  }
}

export function useSafeSvmWallets(): SolanaWalletsHook {
  try {
    return useSolanaWallets();
  } catch {
    return DISCONNECTED_SOLANA_WALLETS;
  }
}

export function useSafeWallets(): WalletsHook {
  try {
    return useWallets();
  } catch {
    return DISCONNECTED_WALLETS;
  }
}

/** Privy embedded EVM wallet client types. `privy` (v1) and `privy-v2` (v2)
 *  are the values `ConnectedWallet.walletClientType` takes for embedded
 *  wallets created within Privy's app (as documented on the `Wallet` type:
 *  "If the value is `privy`, then this is a privy embedded wallet"). External
 *  wallets (MetaMask, Rainbow, …) carry their own client type. */
const PRIVY_EMBEDDED_CLIENT_TYPES = new Set(["privy", "privy-v2"]);

/** Pick the Privy embedded EVM wallet from a `useWallets()` snapshot — the
 *  non-imported, Privy-custodied EOA that the user created on login. Returns
 *  the first match (a user has at most one embedded EVM wallet per Privy
 *  app). External wallets and imported embedded wallets are skipped: external
 *  wallets are surfaced through wagmi connectors, and imported wallets are
 *  not custodied by this Privy app. Used to dispatch the embedded-session
 *  signal so the registry injects a synthetic EVM connection (mirroring the
 *  Para session source), giving the embedded EVM wallet "connected now" /
 *  write capability. */
export function pickPrivyEmbeddedEvmWallet(
  wallets: readonly ConnectedWallet[],
): ConnectedWallet | undefined {
  return wallets.find(
    (wallet) =>
      wallet.type === "ethereum" &&
      !wallet.imported &&
      PRIVY_EMBEDDED_CLIENT_TYPES.has(wallet.walletClientType),
  );
}

function isPrivyEmbeddedEvmUserWallet(
  wallet: unknown,
): wallet is PrivyEmbeddedEvmUserWallet {
  if (!wallet || typeof wallet !== "object") return false;
  const candidate = wallet as PrivyEmbeddedEvmUserWallet;
  return (
    typeof candidate.address === "string" &&
    /^0x[0-9a-fA-F]{40}$/.test(candidate.address) &&
    candidate.imported !== true &&
    (candidate.chainType === undefined ||
      candidate.chainType === "ethereum" ||
      candidate.chainType === "evm") &&
    (candidate.walletClientType === undefined ||
      PRIVY_EMBEDDED_CLIENT_TYPES.has(candidate.walletClientType))
  );
}

export function pickPrivyEmbeddedEvmUserWallet(
  user: PrivyUser,
): PrivyEmbeddedEvmUserWallet | undefined {
  if (!user) return undefined;
  const direct = (user as { wallet?: unknown }).wallet;
  if (isPrivyEmbeddedEvmUserWallet(direct)) return direct;
  const linked = ((user as { linkedAccounts?: unknown[] }).linkedAccounts ??
    []) as unknown[];
  return linked.find(isPrivyEmbeddedEvmUserWallet);
}

function asAomiLoginMethod(
  value: string | undefined,
): AomiLoginMethod | undefined {
  return value && AOMI_LOGIN_METHODS.has(value as AomiLoginMethod)
    ? (value as AomiLoginMethod)
    : undefined;
}

export function inferPrivyAuthMethod(
  user: PrivyUser,
): AomiLoginMethod | undefined {
  if (!user) return undefined;
  const accountTypePriority: Array<[string, AomiLoginMethod]> = [
    ["google_oauth", "google"],
    ["github_oauth", "github"],
    ["apple_oauth", "apple"],
    ["discord_oauth", "discord"],
    ["twitter_oauth", "x"],
    ["telegram", "telegram"],
    ["farcaster", "farcaster"],
    ["email", "email"],
    ["phone", "phone"],
    ["wallet", "wagmi"],
  ];
  const linked = (user.linkedAccounts ?? []) as Array<{ type?: string }>;
  for (const [privyType, label] of accountTypePriority) {
    if (linked.some((acc) => acc?.type === privyType)) return label;
  }
  const first = linked[0]?.type;
  return asAomiLoginMethod(
    typeof first === "string" ? first.toLowerCase() : undefined,
  );
}

export function inferPrivyPrimaryLabel(user: PrivyUser): string | undefined {
  if (!user) return undefined;
  const u = user as unknown as {
    email?: { address?: string };
    google?: { email?: string };
    apple?: { email?: string };
    discord?: { username?: string };
    twitter?: { username?: string };
    github?: { username?: string };
    telegram?: { username?: string; firstName?: string };
    farcaster?: { username?: string; displayName?: string };
    phone?: { number?: string };
  };
  return (
    u.email?.address ??
    u.google?.email ??
    u.apple?.email ??
    u.discord?.username ??
    u.twitter?.username ??
    u.github?.username ??
    u.telegram?.username ??
    u.telegram?.firstName ??
    u.farcaster?.username ??
    u.farcaster?.displayName ??
    u.phone?.number ??
    undefined
  );
}

export function privyLoginMethodsToOptions(
  methods: PrivyClientConfig["loginMethods"] | undefined,
): AomiWalletOption[] {
  const enabledMethods = (methods ?? [])
    .map((method) =>
      asAomiLoginMethod(method === "twitter" ? "x" : String(method)),
    )
    .filter((method): method is AomiLoginMethod => Boolean(method));

  if (enabledMethods.length === 0) return [];

  return [
    {
      id: "privy",
      label:
        enabledMethods.length === 1 && enabledMethods[0] === "google"
          ? "Email or Google"
          : "Email, wallet, or social",
      family: "multichain",
      kind: "social",
      status: "available",
      ready: true,
      description: "Fast account sign-in",
    },
  ];
}

export function toPrivyLoginMethods(
  methods: readonly AuthMethodId[] | undefined,
): PrivyClientConfig["loginMethods"] | undefined {
  if (!methods) return undefined;
  type PrivyLoginMethod = NonNullable<PrivyClientConfig["loginMethods"]>[number];
  const map = {
    apple: "apple",
    discord: "discord",
    email: "email",
    farcaster: "farcaster",
    github: "github",
    google: "google",
    passkey: "passkey",
    phone: "sms",
    telegram: "telegram",
    wallet: "wallet",
    x: "twitter",
  } as const satisfies Partial<
    Record<AuthMethodId, PrivyLoginMethod>
  >;
  const resolved: PrivyLoginMethod[] = [];
  for (const method of methods) {
    const loginMethod = map[method];
    if (loginMethod) resolved.push(loginMethod);
  }
  return resolved.length ? resolved : undefined;
}

/**
 * Single source of truth for the Privy client config shared by the standalone
 * `AomiPrivyProvider` and the additive `PrivyAuthLayer`. The standalone provider
 * passes the extra `defaultChain`/`supportedChains`/`walletConnectProjectId`
 * fields; the additive layer omits them.
 */
export function buildPrivyClientConfig(opts: {
  appLogoUrl?: string;
  appName?: string;
  loginMethods?: PrivyClientConfig["loginMethods"];
  defaultChain?: Chain;
  supportedChains?: readonly Chain[];
  walletConnectProjectId?: string;
}): PrivyClientConfig {
  return {
    appearance: {
      walletList: ["detected_wallets", "metamask", "wallet_connect"],
      logo: opts.appLogoUrl,
    },
    embeddedWallets: {
      ethereum: { createOnLogin: "all-users" },
      solana: { createOnLogin: "all-users" },
    },
    loginMethods: opts.loginMethods,
    ...(opts.defaultChain ? { defaultChain: opts.defaultChain } : {}),
    ...(opts.supportedChains
      ? { supportedChains: opts.supportedChains as unknown as Chain[] }
      : {}),
    ...(opts.walletConnectProjectId
      ? { walletConnectCloudProjectId: opts.walletConnectProjectId }
      : {}),
    ...(opts.appName ? { appName: opts.appName } : {}),
  } as PrivyClientConfig;
}

